from __future__ import division

import unittest

import numpy

from chainer import cuda
from chainer import function
from chainer import testing
from chainer.utils import type_check


class Copy(function.Function):

    """Copy an input GPUArray onto another device."""

    def __init__(self, out_device):
        self.out_device = out_device

    def check_type_forward(self, in_type):
        type_check.expect(in_type.size() == 1)

    def check_type_backward(self, in_types, out_types):
        type_check.expect(out_types.size() == 1)
        type_check.expect(
            in_types[0].type() == out_types[0].type())

    def check_forward(self, x_data):
        x = cuda.cupy.asarray(x_data)
        out = self.forward(x)
        self.assertEqual(x.dtype, out.dtype)
        self.assertEqual(x.shape, out.shape)
        self.assertEqual(x.strides, out.strides)
        self.assertEqual(x.tobytes(), out.tobytes())

    def check_backward(self, x_data, y_grad):
        x = cuda.cupy.asarray(x_data)
        y_grad = cuda.cupy.asarray(y_grad)
        gx = self.backward(x, (y_grad,))[0]
        self.assertEqual(gx.dtype, y_grad.dtype)
        self.assertEqual(gx.shape, y_grad.shape)
        self.assertEqual(gx.tobytes(), y_grad.tobytes())

    def check_forward_cpu(self, x_data):
        x = numpy.asarray(x_data)
        out = self.forward_cpu(x)
        self.assertEqual(x.dtype, out.dtype)
        self.assertEqual(x.shape, out.shape)
        self.assertEqual(x.strides, out.strides)
        self.assertEqual(x.tobytes(), out.tobytes())

    def check_backward_cpu(self, x_data, y_grad):
        x = numpy.asarray(x_data)
        y_grad = numpy.asarray(y_grad)
        gx = self.backward_cpu(x, (y_grad,))[0]
        self.assertEqual(gx.dtype, y_grad.dtype)
        self.assertEqual(gx.shape, y_grad.shape)
        self.assertEqual(gx.tobytes(), y_grad.tobytes())


class CopyDevice(Copy):

    """Copy an input GPUArray onto another device."""

    def __init__(self, out_device):
        self.out_device = out_device

    def forward_cpu(self, x):
        return x[0].copy(),

    def forward_gpu(self, x):
        return cuda.copy(x[0], out_device=self.out_device),

    def backward_cpu(self, x, gy):
        return gy[0].copy(),

    def backward_gpu(self, x, gy):
        return cuda.copy(gy[0], out_device=cuda.get_device(x[0])),


def copy(x, dst):
    """Copies the input variable onto the specified device.

    This function copies the array of input variable onto the device specified
    by ``dst`` if the original array is on GPU, and otherwise just copies the
    array within host memory.

    Args:
        x (~chainer.Variable): Variable to be copied.
        dst: Target device specifier.

    Returns:
        ~chainer.Variable: Output variable.

    """
    return CopyDevice(dst)(x)


