import os


def get_locale_path(locale):
    return join('locale', locale, 'LC_MESSAGES')


def get_translations(locale, domain='django'):
    path = join(get_locale_path(locale), domain + '.po')
    if not isdir(get_locale_path(locale)):
        os.makedirs(get_locale_path(locale))
    if not os.path.exists(path):
        open(path, 'a')
    catalog = Catalog(locale=locale)
    for pot_file in glob(join(get_locale_path(locale), domain + '.pot')):
        catalog.merge(open(pot_file))
    return catalog


class Command(NoArgsCommand):

    option_list = NoArgsCommand.option_list + (
        make_option(
            '--dry-run',
            action='store_true',
            dest='dry_run',
            default=False,
            help='Do not actually save files.'
        ),
    )

    def handle(self, *args, **options):
        if not options['dry_run']:
            pass

        for locale in ['fi']:
            catalog = get_translations(locale)
            if not options['dry_run']:
                with open(join(get_locale_path(locale), 'django.po'), 'w') as po_file:
                    write_po(po_file, catalog)


